import json
def C(title,scen,prompt,cues,target,en,can):
    return {"tier":"tier1","level":"B2","title":"Communicative Challenge: "+title,"scenario":scen,"prompt":prompt,"cues":cues,"target":target,"english":en,"canDo":can}
d={
'b2-costarica-01':C('Where Turtles Lay Eggs','You are Meg. You and Carlos are planning a trip to Costa Rica, and he asks you where the green turtles lay their eggs.','Tell Carlos where the turtles lay their eggs, putting the place in the spotlight.',['Start with the place','Say what the turtles do there'],'Es en Tortuguero, en la costa del Caribe, donde desovan las tortugas verdes.','It is in Tortuguero, on the Caribbean coast, that the green turtles lay their eggs.','I can put a place, a time or an idea in the spotlight with *Fue… donde / cuando* and *Lo que… es…*.'),
'b2-costarica-02':C('A Country Without an Army','You are Carlos. You and Meg are watching a documentary about Costa Rica, and she asks you if the country has no security at all.','Correct her idea and say who provides security.',['Reject the wrong reason','Give the true one'],'No es que Costa Rica no tenga seguridad, sino que la dan policías civiles.','It is not that Costa Rica has no security, but that civilian police provide it.','I can correct a reason with *No es que… sino que…*.'),
'b2-costarica-03':C('The Fact That','You are Meg. You and Carlos are reading an article about the CCSS, and he asks you what challenge the health system has.','Comment on the fact that the population is getting older.',['Start with the known fact','Say what it creates'],'El hecho de que la población envejezca crea nuevos retos para la CCSS.','The fact that the population is getting older creates new challenges for the CCSS.','I can comment on a known fact with *el hecho de que* + subjunctive.'),
'b2-costarica-04':C('Before the Visitors Arrive','You are Carlos. You and Meg are planning a visit to a national park, and she asks what the guides do before the groups come.','Tell Meg what the guides do and when.',['Say what the guides check','Say that they do it before the visitors arrive'],'Los guías revisan los senderos antes de que lleguen los visitantes.','The guides check the trails before the visitors arrive.','I can say what happened before or after someone else\'s action, with *antes de que* and *después de que*.'),
'b2-costarica-05':C('What the Unions Want','You are Meg. You and Carlos are reading a report about pineapple farms in Costa Rica, and he asks you what the unions want.','Tell Carlos what the unions want from the companies.',['Say who wants something','Say what the companies should do'],'Los sindicatos quieren que las empresas paguen el salario mínimo.','The unions want the companies to pay the minimum wage.','I can choose between an infinitive and *que* + subjunctive, depending on who does the second action.'),
'b2-costarica-consolidation':C('Review: Costa Rica','You are Carlos. You and Meg are planning a trip to Costa Rica, and she asks what you remember about the country.','Tell Meg one fact about nature and one about the army.',['Put what surprises you in the spotlight','Correct the idea that the country has no police'],'Lo que más sorprende en Costa Rica es la variedad de especies. No es que no tenga policía, sino que no tiene ejército.','What surprises most in Costa Rica is the variety of species. It is not that it has no police, but that it has no army.','I can review what I learned about Costa Rica, from its volcanoes to its regions.')}
json.dump(d,open('/home/user/parlour-read-a/challenges-costa-rica.json','w'),ensure_ascii=False,indent=2)
